import type { Metadata, Viewport } from 'next';
import { connection } from 'next/server';
import { allFontVariables } from './fonts';
import './globals.css';

export const metadata: Metadata = {
  title: 'Atable',
  robots: { index: false, follow: false },
};

export const viewport: Viewport = {
  width: 'device-width',
  initialScale: 1,
};

// Every page is rendered at request time: the CSP nonce generated by proxy.ts must be applied to
// the scripts of each response (vol. 05 §6), which static prerendering cannot do (ADR-010).
export default async function RootLayout({ children }: { children: React.ReactNode }) {
  await connection();
  return (
    <html lang="fr" className={allFontVariables}>
      <body className="min-h-dvh antialiased">{children}</body>
    </html>
  );
}
